project GNAT2Why_GNAT is

   for Object_Dir use "obj";
   for Exec_Dir use "../install/bin";

   for Source_Dirs use ("obj", "gnat_src", "obj-gnat");
   for Excluded_Source_Files use ("back_end.adb",
                                  "gnat1drv.adb",
                                  "indepsw-aix.adb",
                                  "indepsw-darwin.adb",
                                  "indepsw-gnu.adb");

   type Build_Type is ("Debug", "Devel", "Production");
   --  Debug: all checks enabled
   --  Devel: inexpensive checks enabled, expensive checks disabled
   --  Production: all checks disabled

   Build : Build_Type := External ("Build", "Devel");
   Coverage := External ("Coverage", "");

   Tool := External ("GPR_TOOL", "");

   Common_Switches := ("-g", "-gnat2022");
   --  These are appended after other switches, in particular, after -gnatg,
   --  which sets the Ada version to 2012.

   case Coverage is
     when "yes" =>
       Common_Switches := Common_Switches & ("-O0");
     when others =>
       null;
   end case;

   package Compiler is
      for Local_Configuration_Pragmas use "gnat.adc";

      case Build is
         when "Debug" | "Devel" =>
            for Switches ("Ada") use
               ("-O0", "-gnatg", "-gnata", "-gnatVa") & Common_Switches;
         when "Production" =>
            for Switches ("Ada") use
               ("-O2", "-gnatg", "-gnatpn", "-gnatwn") & Common_Switches;
      end case;
   end Compiler;

   package Builder is
      for Executable ("gnat1drv.adb") use "gnat2why";

      case Build is
         when "Debug" =>
            for Global_Configuration_Pragmas use "debug.adc";
         when "Devel" =>
            for Global_Configuration_Pragmas use "devel.adc";
         when "Production" =>
            null;
      end case;

      for Switches ("Ada") use ("-m");

      case Tool is
         when "gnatsas" =>
            --  Use -gnateb to ensure that pragma configuration files checksums are
            --  correctly computed when running incremental analysis in CIs.
            for Global_Compilation_Switches ("Ada") use ("-gnateb");
         when Others =>
            null;
      end case;

   end Builder;

   package Coverage is
      --  This clause is needed to make front end instrumentation work, it'd be
      --  nice to find out why???
      for Excluded_Units use ("Gnat1drv");
   end Coverage;

   package Naming is
      for Body ("Get_Targ") use "ada_get_targ.adb";
   end Naming;

   package Format is
     for Ignore use "gnat_ignore_format.txt";
   end Format;


end GNAT2Why_GNAT;

project Gnat2Why_C is
   for Languages use ("C");
   for Source_Dirs use (".", "../src/utils");
   for Object_Dir use "obj";
end Gnat2Why_C;

with "gnatcoll_core";

project Helpers is

   for Source_Dirs use (".", "..");

   for Main use ("xtree");

   for Object_Dir use "obj";

   for Exec_Dir use ".";

   package Compiler is
      for Default_Switches ("ada") use ("-g", "-O0", "-gnata", "-gnatg");
   end Compiler;

   package Builder is
      for Switches ("Ada") use ("-m");
   end Builder;

end Helpers;

pragma Restrictions (No_Tasking);
pragma Restrictions (No_Asynchronous_Control);
pragma Restrictions (Max_Asynchronous_Select_Nesting => 0);
pragma Restrictions (No_Abort_Statements);

pragma Restrictions (No_Implicit_Dynamic_Code);

--  Dependency on Ada.Real_Time forces the use of GNAT tasking runtime,
--  which adds extra checks for each memory allocation and deallocation.
pragma Restrictions (No_Dependence => Ada.Real_Time);

--  Attribute Update is soon to be obsoleted and then deconstructed
pragma Restrictions (No_Use_Of_Attribute => Update);

--  Currently we don't use Ada.Streams, so by announcing this to the compiler,
--  we can benefit from smaller executables and faster compilation time (~2%).
pragma Restrictions (No_Streams);

